<script setup lang="ts">import {useResearch} from '../stores/research';import {runStatus} from '../constants/enums';import {useTask} from '../hooks/useTask';import ErrorNotice from './common/ErrorNotice.vue';const research=useResearch(),{error,perform}=useTask();</script><template><div><label class="run-select">冻结研究<select aria-label="选择权衡结果" :value="research.selected" @change="perform(()=>research.select(Number(($event.target as HTMLSelectElement).value)))"><option v-for="r in research.runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}} · {{runStatus[r.status]}}</option></select></label><ErrorNotice :error="error"/></div></template>